package com.coffeeshop.service;import com.coffeeshop.dto.CustomerCommands;import com.coffeeshop.model.CustomerModels;import com.coffeeshop.repository.CustomerRepository;import java.util.*;public final class CustomerService{private final CustomerRepository repository;public CustomerService(CustomerRepository r){repository=Objects.requireNonNull(r);}public List<CustomerModels.Customer>customers(String search,Boolean active){return repository.find(search,active);}public List<CustomerModels.Option>activeOptions(){return repository.activeOptions();}public long save(CustomerCommands.Save q){if(q==null)throw new IllegalArgumentException("Customer details are required.");String first=required(q.firstName(),100,"First name");String email=optional(q.email(),254,"Email");if(email!=null&&(!email.contains("@")||email.startsWith("@")||email.endsWith("@")))throw new IllegalArgumentException("Enter a valid email address.");if(q.id()!=null&&(q.rowVersion()==null||q.rowVersion().length==0))throw new IllegalArgumentException("Refresh this customer and try again.");return repository.save(new CustomerCommands.Save(q.id(),first,optional(q.lastName(),100,"Last name"),optional(q.legalName(),200,"Legal name"),optional(q.taxNumber(),100,"Tax registration number"),optional(q.phone(),30,"Phone"),email,optional(q.notes(),1000,"Notes"),q.active(),q.rowVersion()));}public void setActive(CustomerModels.Customer c,boolean active){Objects.requireNonNull(c);repository.setActive(c.id(),active,c.rowVersion());}private static String required(String v,int max,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>max)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int max,String n){return v==null||v.isBlank()?null:required(v,max,n);}}
